import{_ as a,o as d,c as r,ag as e}from"./chunks/framework.C5oN-8Wt.js";const g=JSON.parse('{"title":"低空通信、导航与监视：从状态回传开始","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/learn/index.md","filePath":"v0.3.0-alpha/learn/index.md"}'),o={name:"v0.3.0-alpha/learn/index.md"};function h(n,t,l,s,i,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="低空通信、导航与监视-从状态回传开始" tabindex="-1">低空通信、导航与监视：从状态回传开始 <a class="header-anchor" href="#低空通信、导航与监视-从状态回传开始" aria-label="Permalink to &quot;低空通信、导航与监视：从状态回传开始&quot;">​</a></h1><p>无人机的高度、速度和位置，怎样出现在地面站？这条学习路径从这个问题开始。你只需会读坐标、做乘除，不必先学通信原理、复数或傅里叶变换。遇到新词，先看它在本课解决什么问题，再动手验证。</p><p>适用 <strong>CNS Master v0.3.0-alpha</strong>，PC 本地 GNU Radio 仿真。下载工程不需要实验箱、飞控、服务器或账号。这里讲的是通信信号的基础模型；位置数据的传输与计算位置的方法不同，通信部分先研究信号传输模型；新增的导航与监视部分使用平面测距和延迟模型，不做真实卫星定位、电台收发或雷达采集。</p><h2 id="按什么顺序学" tabindex="-1">按什么顺序学 <a class="header-anchor" href="#按什么顺序学" aria-label="Permalink to &quot;按什么顺序学&quot;">​</a></h2><p>每次只做一课。先写下自己的预测，运行后再用坐标和数据解释观察结果。01 建立全貌，02—06 认识实数信号，07 再引入两个坐标，08—09 走两条不同的调制／判决入门路线。</p><table tabindex="0"><thead><tr><th>顺序</th><th>低空应用问题</th><th>本课完成的事</th></tr></thead><tbody><tr><td><a href="./01-link-overview/">01 链路全貌</a></td><td>地面站读到高度，要经过哪些环节？</td><td>区分数据、信号、网络与显示；可选运行一段简单处理链。</td></tr><tr><td><a href="./02-wave-quantities/">02 幅度、频率与相位</a></td><td>怎样准确描述通信中的周期变化？</td><td>对照两路波形，分别改变高低、快慢和起始位置。</td></tr><tr><td><a href="./03-sampling/">03 采样</a></td><td>计算机怎样表示连续变化？</td><td>数每周期的点，解释四点折线为什么不是三角波。</td></tr><tr><td><a href="./04-signal-views/">04 三种观察视图</a></td><td>一条波形里同时有几种变化？</td><td>把时域的起伏、频谱的峰与瀑布的频率轨迹对应起来。</td></tr><tr><td><a href="./05-noise/">05 噪声</a></td><td>接收信号为什么不再平滑？</td><td>将随机变化与有规律变化相加，比较噪声幅度。</td></tr><tr><td><a href="./06-filter/">06 滤波</a></td><td>怎样保留一部分变化、压低另一部分？</td><td>比较低通前后的两个频率，认识滤波的限制。</td></tr><tr><td><a href="./07-iq/">07 I/Q</a></td><td>一个数不够表示幅度和相位时怎么办？</td><td>从平面坐标理解 I/Q，认识旋转方向和星座视图。</td></tr><tr><td><a href="./08-fm/">08 调频与解调</a></td><td>数值怎样控制信号的转动快慢？</td><td>让常量控制频率，再用相邻样本的角度变化还原数值。</td></tr><tr><td><a href="./09-symbols/">09 码元与判决</a></td><td>离散数据怎样选一个信号点？</td><td>用 QPSK 映射和理想硬判决，区分索引、坐标与比特。</td></tr></tbody></table><p>08 的模拟调频与 09 的离散码元映射分别学习，不把前者自动当成后者的完整收发机。</p><h2 id="从信号实验走向定位与监视" tabindex="-1">从信号实验走向定位与监视 <a class="header-anchor" href="#从信号实验走向定位与监视" aria-label="Permalink to &quot;从信号实验走向定位与监视&quot;">​</a></h2><p>完成通信入门后，可继续三课；也可直接从熟悉的平面坐标进入第 10 课。</p><table tabindex="0"><thead><tr><th>顺序</th><th>低空应用问题</th><th>本课完成的事</th></tr></thead><tbody><tr><td><a href="./01-position-from-ranges/">10 三段距离求位置</a></td><td>已知无人机到三个锚点的距离，怎样求位置？</td><td>由勾股定理生成距离，再解回二维坐标。</td></tr><tr><td><a href="./02-find-delay/">11 相关找延迟</a></td><td>怎样知道一段接收信号比参考晚了多久？</td><td>移动短序列手算相关，读出峰对应的 lag。</td></tr><tr><td><a href="./03-delay-to-distance/">12 延迟换距离</a></td><td>怎样把样本延迟换成米？</td><td>先换算秒，再区分单程和往返传播。</td></tr></tbody></table><p>第 10 课独立完成，第 11、12 课连续学习。相关器以 N 点为一帧，本课采用 N=8、参考源样本数 Q=64；Q 须至少为 N 且能被 N 整除，不自动补尾。位置与距离向量须显式选择分量；完整相关帧使用单路 lag 显示。它们是 PC 教学模型，不能仅凭模型中的峰判断发现真实目标。</p><h2 id="第一次操作先看这里" tabindex="-1">第一次操作先看这里 <a class="header-anchor" href="#第一次操作先看这里" aria-label="Permalink to &quot;第一次操作先看这里&quot;">​</a></h2><ol><li>下载某课的 <code>.cnsproj</code>，放到个人文件夹。启动 Master，准备就绪后点击“进入”；用“文件 → 打开工程”（<strong>Ctrl+O</strong>）选择文件。安装版请使用程序内打开。</li><li>工程已保存模块、接线和观察器绑定。通过“视图 → 分析工具”找回仍存在的观察器窗口。在“参数”页核对捕获变量；如果自己重建，从“编辑 → 插入 → 观察器”创建窗口，在输入框键入节点名，从候选中<strong>确认</strong>它的输出。多路时点击“添加捕获变量”，最多 4 路。</li><li>通信入门 01—09 课建议先把流程图的“参考源样本数”设为 <strong>4096</strong>，按 <strong>F5</strong> 运行。状态完成后看实际缓存；不是打开工程就有预制结果。<strong>Ctrl+F5</strong> 只准备，不会产生运行数据。要持续看瀑布，设 <strong>0</strong> 后运行，最后按 <strong>Shift+F5</strong> 停止。</li><li>图上的横轴默认是样本时间，单位秒（s）；纵轴按本路实际单位读。点“自动刻度”恢复范围，也可用刻度旁的 <strong>+／−</strong>。滚轮缩放，Shift＋滚轮只调横轴。运行中拖动回看会保留一段当时数据，点“自动刻度”／“自动范围”回到最新数据。</li><li>做对照时先 <strong>Shift+F5</strong> 停止，只改指定的一个参数，再按 <strong>F5</strong>。这样避免把旧缓存误当成新参数结果。保存对照工程用“另存为”（<strong>Ctrl+Shift+S</strong>），保留原文件作参照。</li></ol><p>新准备会清空上次数据；重新打开只恢复配置和已有运行快照，不恢复样本或进程。普通关闭观察器会移除该实例及其绑定，工程因此未保存；需要暂时让开时可最小化窗口。切换到其他工程时当前任务继续运行；运行另一个工程会先结束前一个任务。关闭工程时按程序提示处理未保存内容与关联工具。</p><h2 id="先记住四种不同的量" tabindex="-1">先记住四种不同的量 <a class="header-anchor" href="#先记住四种不同的量" aria-label="Permalink to &quot;先记住四种不同的量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>量</th><th>本课程中的含义</th><th>不要混淆</th></tr></thead><tbody><tr><td>信号频率 f，Hz</td><td>一秒重复多少个周期</td><td>不等于每秒传多少条高度消息。</td></tr><tr><td>采样率 Fs，sample/s</td><td>一秒给同一路信号取多少个数</td><td>本组标量工程每个 item 就是一个样本；不是画面刷新次数。</td></tr><tr><td>幅度</td><td>相对参考大小，本组多为归一化幅度</td><td>没有标定时不能称为伏特、米或发射功率。</td></tr><tr><td>码元索引</td><td>从若干种选择中选第几个，09 中为 0—3</td><td>不是模拟幅度，也不是一条完整的遥测报文。</td></tr></tbody></table><p>阅读曲线时问自己：输入来自哪个节点？坐标是什么？运行的是哪组参数？若三点不清楚，先回参数页核对。教程中的静态参考曲线用于解释一组实际计算结果，Master 的实时图仍来自你本次运行。点击参考图可单独打开原始 SVG，再用浏览器缩放读清坐标与样本点。</p><h2 id="做完短实验以后" tabindex="-1">做完短实验以后 <a class="header-anchor" href="#做完短实验以后" aria-label="Permalink to &quot;做完短实验以后&quot;">​</a></h2><p>能解释每课的对照结果后，再读<a href="./../">模块手册</a>，按需要查完整参数与限制。原有综合示例仍从模块文章下载：例如<a href="./../modules/low_pass/#下载与观察">实数处理</a>用于串联运算与三种滤波，<a href="./../modules/iq_split/#下载与观察">复数与 I/Q</a>串联复数处理，<a href="./../modules/channel_model/#下载与观察">QPSK 与信道</a>增加信道影响。信道有原生前视，不能直接按输入输出同索引判错，先读该模块的说明。</p><p>可以把不同短实验组合成自己的工程，但先一次增加一个环节，并保留处理前的观察分支。得到一张好看的图以后，还要能说明它能证明什么、不能证明什么。</p><p><a href="./01-link-overview/">从 01 链路全貌开始 →</a></p>',21)])])}const c=a(o,[["render",h]]);export{g as __pageData,c as default};
